#!/bin/bash
set +e -x -o pipefail
# AmpliconSuite-pipeline 0.0.1
# Generated by dx-app-wizard.
#
# Basic execution pattern: Your app will run on a single machine from
# beginning to end.
#
# Your job's input variables (if any) will be loaded as environment
# variables before this script runs.  Any array inputs will be loaded
# as bash arrays.
#
# Any code outside of main() (or any entry point you may add) is
# ALWAYS executed, followed by running the entry point itself.
#
# See https://documentation.dnanexus.com/developer for tutorials on how
# to modify this file.

main() {
    # cwd is $HOME=/home/dnanexus/

    ## Process inputs
    # On startup, home directory structure is defined by inputSpec in dxapp.json:
    # $HOME
    # ├── in
    # │   ├── bam
    # │   │   └── RCMB56_P1.nodup.bam
    # │   ├── index
    # │   │   └── RCMB56_P1.nodup.bam.bai
    # │   ├── data_repo
    # │   │   └── GRCh38.tar.gz
    # │   └── mosek_lic
    # │       └── mosek.lic
    # │ ...
    # Environment variables are predefined for each input: $input, $input_path, $input_name $input_prefix
    # See https://documentation.dnanexus.com/developer/apps/bash#downloading-and-using-file-inputs

    dx-download-all-inputs
    mv $index_path $(dirname ${bam_path})     # expects .bam.bai file in same directory as .bam

    # Set required environment variables
    export AA_DATA_REPO=$HOME/in/data_repo
    export MOSEKLM_LICENSE_FILE=$HOME/in/mosek_lic
    export AA_SRC=/resources/AmpliconSuite-pipeline/

    # pull and install AmpliconSuite-pipeline
    # Note that dh puts a cap on 200 requests per day
    docker pull jluebeck/prepareaa:latest
    #source $AA_SRC/install.sh --finalize_only

    # Unpack data_repo
    cd $AA_DATA_REPO
    tar zxf $data_repo_name
    rm $data_repo_name
    touch ${AA_DATA_REPO}/coverage.stats
    chmod a+rw ${AA_DATA_REPO}/coverage.stats
    cd $HOME

    ## Parse and run command
    # Locations of executables are defined in dxapp.json.

    cmd="python3 ${AA_SRC}/docker/run_paa_docker.py --sample_name ${bam_prefix} --nthreads 8 --bam ${bam_path} --ref $ref --cngain $cngain --run_AA --output_directory $HOME/out"
    eval $cmd

    ## Export outputs
    # Outputs must be configured as defined by outputSpec in dxapp.json:
    # $HOME
    # ├── out
    # │   └── $bam_prefix
    # │       │ ...
    # │ ...

    dx-upload-all-outputs
}
